const body = $('Webhook').first().json.body;
const brandData = $('Fetch Brand Data').first().json;

const brandName = brandData.brands?.name || 'Unknown Brand';
const brandStyle = brandData.infographic_md || brandData.style_prompt || '';
if (!brandStyle) throw new Error('No brand guidelines found for this brand.');

const brandLogoUrl = brandData.logo_url || null;
const adCopy = body.adCopy || '';
const layoutReferenceId = body.layoutReferenceId || null;
if (!adCopy) throw new Error('adCopy is required.');

const allRefs = $('Fetch Infographic Layouts').all().map(r => r.json);
let layoutRef = null;
if (allRefs.length > 0) {
  if (layoutReferenceId) {
    layoutRef = allRefs.find(r => r.id === layoutReferenceId) || allRefs[Math.floor(Math.random() * allRefs.length)];
  } else {
    layoutRef = allRefs[Math.floor(Math.random() * allRefs.length)];
  }
}

const logoUrl = brandLogoUrl;

const systemPrompt = [
  'You are a professional Creative Technologist specializing in Canvas API motion graphics.',
  'Generate valid JavaScript code for a 1080x1080 animated social media infographic.',
  '',
  'CRITICAL TECHNICAL RULES:',
  '1. FUNCTION SIGNATURE: You MUST use a named function declaration exactly like this:',
  '   function drawGraphic(ctx, width, height, logoImg, options) { ... }',
  '   No arrow functions. No variable assignment. No export. No async/await.',
  '2. Output ONLY a valid JSON object: { "jsCode": "...", "designExplanation": "..." }',
  '   No markdown. No code fences.',
  '3. OPTIONS ARGUMENT: { progress, frame, fps, durationInFrames, adCopy, theme }',
  '   - progress: 0.0 to 1.0 — use for ALL animation.',
  '   - adCopy is a plain STRING. Use .split(), .trim(), .includes(). NEVER .map() or .filter() directly on it.',
  '4. Path2D: ALWAYS use ctx.fill(path) and ctx.stroke(path). NEVER path.fill() or path.stroke().',
  '5. Use ctx.roundRect() — NOT ctx.roundedRect().',
  '6. Declare ALL variables with const/let BEFORE use. No hoisting assumptions.',
  '',
  'THEME SUPPORT — MANDATORY:',
  'At the very start of drawGraphic, define a complete theme-aware color palette using brand guidelines:',
  '  const isDark = options.theme === \'dark\';',
  '  const colors = isDark ? {',
  '    bg: \'...\',         // dark background — from brand guidelines',
  '    surface: \'rgba(18,21,35,0.75)\',  // translucent dark card fill',
  '    textPrimary: \'...\',',
  '    textSecondary: \'...\',',
  '    accent: \'...\',     // brand primary accent color',
  '    border: \'...\',',
  '    glow: \'...\',       // glowing accent e.g. rgba(r,g,b,0.45)',
  '  } : {',
  '    bg: \'...\',         // light background — from brand guidelines',
  '    surface: \'rgba(255,255,255,0.92)\', // glassmorphic white card',
  '    textPrimary: \'...\',',
  '    textSecondary: \'...\',',
  '    accent: \'...\',',
  '    border: \'...\',',
  '    shadow: \'rgba(0,0,0,0.10)\',',
  '  };',
