  '',
  'SAFE AREA & COORDINATE BUDGET — CRITICAL (1080x1080 canvas):',
  '  Safe area: x 72–1008, y 72–1008. Working area = 936x936px.',
  '  Logo at y=72. Content MUST start at y >= 220 (leave 100–130px gap below logo).',
  '  Card container: cardY = 200–240. cardH = 640–720. MUST satisfy: cardY + cardH <= 920.',
  '  Inside card padding: 40–50px.',
  '  ALWAYS track vertical position with a currentY variable:',
  '    let currentY = cardY + padding;',
  '    // draw element...',
  '    currentY += elementHeight + gap;',
  '  Anchor ALL subsequent elements to currentY — NEVER hardcode y-coordinates for stacked elements.',
  '  Badges, CTAs, source notes: y = currentY + gap. Never hardcoded.',
  '',
  'SPACING TOKENS — use only these values:',
  '  16px = micro | 24px = tight | 32px = standard | 48px = section | 64px = hero | 72px = zone',
  '',
  'TYPOGRAPHY:',
  '  Hero stat: 110–130px | Headline: 32–42px (max-width 700px)',
  '  Subheadline: 24–32px | Body/labels: 18–28px | CTA: 20–26px',
  '  Font: follow brand guidelines. Default: Inter, sans-serif.',
  '  TEXT WRAPPING — MANDATORY for all text blocks. Always measure first:',
  '    const words = text.split(\' \');',
  '    let line = \'\', lines = [];',
  '    for (const word of words) {',
  '      const test = line + (line ? \' \' : \'\') + word;',
  '      if (ctx.measureText(test).width > maxWidth && line) { lines.push(line); line = word; }',
  '      else line = test;',
  '    }',
  '    if (line) lines.push(line);',
  '    lines.forEach((l, i) => ctx.fillText(l, x, y + i * lineHeight));',
  '',
  'COUNT-UP ANIMATION — mandatory for ALL numbers/percentages/metrics:',
  '  const easedProgress = 1 - Math.pow(1 - Math.min(1, options.progress * 1.5), 3);',
  '  const currentVal = Math.floor(targetValue * easedProgress);',
  '',
  'VISUAL STYLE — apply from brand guidelines:',
  '  Light mode: soft-gradient or solid light bg. Pure-white glassmorphic cards.',
  '    Card shadow: ctx.shadowColor = colors.shadow; ctx.shadowBlur = 28; ctx.shadowOffsetY = 14;',
  '    Thin transparent border on cards. Dark high-contrast text. Brand accent colors.',
  '  Dark mode: deep dark gradient bg with animated dot-grid (grid offset drifts: offset += options.progress * 0.5).',
  '    Translucent card fill (colors.surface). Thin glowing accent border on cards.',
  '    Glow on hero stats: ctx.shadowColor = colors.glow; ctx.shadowBlur = 36; ctx.shadowOffsetY = 0;',
  '    White/silver high-contrast text.',
  '  ALWAYS reset shadow after every shadowed element:',
  '    ctx.shadowColor = \'transparent\'; ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;',
  '',
  'ANIMATION — MANDATORY (use options.progress for all motion):',
  '  const ease = t => 1 - Math.pow(1 - Math.min(1, t), 3);',
  '  Stagger all element entrances sequentially:',
  '    Background/pattern: 0–0.10 | Logo: 0.05–0.20 | Headline: 0.15–0.35',
  '    Cards/stats: 0.30–0.65 | Body copy: 0.50–0.80 | CTA/source note: 0.70–0.95',
  '  Animation techniques:',
  '    Fade in via ctx.globalAlpha = ease(progress_in_range)',
  '    Slide up: drawY = targetY + (1 - eased) * 40',
  '    Count-up numbers (mandatory for all stats)',
  '    Bars grow left-to-right based on progress',
  '    Lines draw progressively',
  '  Always restore ctx.globalAlpha = 1 after fade-in elements.',
  '',
  'CTA RULE: Only render a CTA button if the ad copy explicitly contains a call-to-action.',
  '  If absent — do NOT add one, do NOT reserve CTA space. Redistribute the layout vertically.',
  '',
  'MEANING PRESERVATION:',
  '  Use only text, numbers, and claims present in the ad copy.',
  '  Do NOT invent statistics, benefits, or CTA text not in the copy.',
].join('\n');

const MESSAGE_FOCUS_LABELS = {
  stat_lead: 'Data Insight / Stat Lead — built around a key number, percentage, or metric',
  pain_point: 'Address Pain Point — calls out a problem the audience faces',
  solution: 'Solution Capability — highlights what the product/service does or enables',
  proof: 'Proof / Trust Signal — uses testimonials, case studies, awards, or social proof',
  education: 'Education / How It Works — explains a process, concept, or framework',
};
const CREATIVE_HOOK_LABELS = {
  hero_stat: 'Hero Stat — one dominant number is the visual centrepiece',
  multi_stat: 'Multi-Stat Grid — 2–4 stats in a card grid layout',
  headline_lead: 'Bold Headline Lead — large typographic statement, minimal other elements',
  data_viz: 'Data Visualisation — chart, bar, progress ring, or graph as centrepiece',
  process_flow: 'Step / Process Flow — sequential steps or timeline structure',
};

const messageFocusIds = (body.messageFocus || []);
const creativeHookIds = (body.creativeHook || []);

const fontHeading = brandData.infographic_font_heading || null;
const fontBody = brandData.infographic_font_body || null;

let userPromptText = 'Brand: ' + brandName + '\n\nBrand Guidelines:\n' + brandStyle + '\n\nAd Copy:\n' + adCopy + '\n\nLogo Provided: ' + (logoUrl ? 'Yes' : 'No') + '\n';

if (fontHeading || fontBody) {
  userPromptText += '\n\nINFOGRAPHIC FONTS — mandatory, use ONLY these font family names in ctx.font:';
  if (fontHeading) userPromptText += '\n- Heading font (headlines, hero stats, card numbers, all large text): "' + fontHeading + '"';
  if (fontBody) userPromptText += '\n- Body font (subheadlines, labels, captions, all small text): "' + (fontBody || fontHeading) + '"';
  if (fontHeading) userPromptText += '\n  Example: ctx.font = \'900 64px "' + fontHeading + '"\'';
  if (fontBody) userPromptText += '\n  Example: ctx.font = \'400 18px "' + (fontBody || fontHeading) + '"\'';
  userPromptText += '\n  Do NOT use any other font family name. These fonts are pre-loaded in the browser.';
}

if (messageFocusIds.length > 0) {
  userPromptText += '\nMessage Focus (chosen by user — let this drive content emphasis):';
  messageFocusIds.forEach(id => {
    if (MESSAGE_FOCUS_LABELS[id]) userPromptText += '\n- ' + MESSAGE_FOCUS_LABELS[id];
  });
}

if (creativeHookIds.length > 0) {
  userPromptText += '\nCreative Hook (chosen by user — let this drive the visual layout):';
  creativeHookIds.forEach(id => {
    if (CREATIVE_HOOK_LABELS[id]) userPromptText += '\n- ' + CREATIVE_HOOK_LABELS[id];
  });
}

if (layoutRef) {
  userPromptText += '\nLayout Reference: ' + layoutRef.name;
  if (layoutRef.description) userPromptText += '\n' + layoutRef.description;
  if (layoutRef.image_url) userPromptText += '\nMatch the spatial composition and visual proportions from this reference image closely.';
}

const userContent = (layoutRef && layoutRef.image_url)
  ? [
      { type: 'text', text: userPromptText },
      { type: 'image_url', image_url: { url: layoutRef.image_url } }
    ]
  : userPromptText;

const messages = [
  { role: 'system', content: systemPrompt },
  { role: 'user', content: userContent }
];

const requestBody = JSON.stringify({
  model: 'google/gemini-3.5-flash',
  messages: messages,
  max_tokens: 32000
});

return [{ json: { brandId: body.brandId, brandName: brandName, logoUrl: logoUrl, layoutRefUsed: layoutRef?.name || null, requestBody: requestBody } }];

const rendererResponse = $('Call Gemini 2.5 Pro').first().json;
const meta = $('Build Prompt').first().json;
const body = $('Webhook').first().json.body;

const raw = rendererResponse.choices?.[0]?.message?.content;
if (!raw) throw new Error('No content from renderer: ' + JSON.stringify(rendererResponse));

let cleaned = raw.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```[\w]*\n?/, '').replace(/\n?```$/, '').trim();
}

function fixJsonEscapes(str) {
  return str.replace(/\\(?!["\\/bfnrtu])/g, '\\\\');
}

// Reverses JSON-style backslash escaping in a single left-to-right pass. A naive chain of
// sequential .replace(/\\n/g,...).replace(/\\\\/g,...) calls is order-unsound: an escaped
// backslash immediately followed by a literal "n" (e.g. from a regex like /\d/ that the model
// double-escaped) gets its trailing \n consumed by the newline rule first, leaving a stray
// backslash in the output that later breaks `new Function(...)` with "Invalid escape in
// identifier" / "Invalid or unexpected token". A single regex.replace with alternation consumes
// matched characters left-to-right without re-scanning replaced output, so this is order-safe.
function unescapeJsonEscapes(str) {
  return str.replace(/\\(u[0-9a-fA-F]{4}|n|t|r|"|'|\\)/g, function (_m, token) {
    switch (token[0]) {
      case 'n': return '\n';
      case 't': return '\t';
      case 'r': return '\r';
      case '"': return '"';
      case "'": return "'";
      case '\\': return '\\';
      default: return String.fromCharCode(parseInt(token.slice(1), 16));
    }
  });
}

function extractFromTruncated(str) {
  const m = str.match(/"jsCode"\s*:\s*"((?:[^"\\]|\\.)*)/s);
  if (!m || m[1].length < 100) return null;
  let code = unescapeJsonEscapes(m[1]);
  if (!code.trim().endsWith('}')) {
    // Find the last "safe" statement boundary — back at exactly one level of curly nesting
    // (the function body itself) with zero open parens/brackets, and not inside a string
    // literal. Older code just grabbed the LAST '}' or ';' anywhere in the string, which can
    // land inside a string literal (e.g. ctx.fillText('Save 20% {bonus}', ...)) and produce
    // code that's still broken after appending the closing brace.
    let depthCurly = 0, depthParen = 0, depthSquare = 0;
    let inString = null;
    let bestCut = -1;
    for (let i = 0; i < code.length; i++) {
      const ch = code[i];
      if (inString) {
        if (ch === '\\') { i++; continue; }
        if (ch === inString) inString = null;
        continue;
      }
      if (ch === "'" || ch === '"' || ch === '`') { inString = ch; continue; }
      if (ch === '{') depthCurly++;
      else if (ch === '}') {
        depthCurly--;
        if (depthCurly === 1 && depthParen === 0 && depthSquare === 0) bestCut = i;
      } else if (ch === '(') depthParen++;
      else if (ch === ')') depthParen--;
      else if (ch === '[') depthSquare++;
      else if (ch === ']') depthSquare--;
      else if (ch === ';' && depthCurly === 1 && depthParen === 0 && depthSquare === 0) bestCut = i;
    }
    if (bestCut < 100) return null;
    code = code.substring(0, bestCut + 1) + '\n}';
  }
  return code;
}

let jsCode = null;
let designExplanation = '';

try {
  const parsed = JSON.parse(cleaned);
  jsCode = parsed.jsCode || null;
  designExplanation = parsed.designExplanation || '';
} catch(e) {
  try {
    const parsed = JSON.parse(fixJsonEscapes(cleaned));
    jsCode = parsed.jsCode || null;
    designExplanation = parsed.designExplanation || '';
  } catch(e2) {
    jsCode = extractFromTruncated(cleaned);
  }
}

if (!jsCode) throw new Error('Could not extract jsCode from renderer: ' + cleaned.substring(0, 300));
const adCopy = body.adCopy || '';

const systemPrompt = [
  'You are the Layout Validation + Auto-Correction Layer for a JS Canvas social media infographic.',
  'Review the provided drawGraphic JavaScript function for layout issues and return a corrected version.',
  '',
  'Canvas: 1080x1080px. Safe area: x 72–1008, y 72–1008.',
  '',
  'VALIDATE AND FIX ALL OF THE FOLLOWING — check every issue:',
  '',
  '1. SAFE AREA: No element drawn outside x:72–1008 or y:72–1008.',
  '   Fix: move element inward or reduce its size.',
  '',
  '2. LOGO HANDLING: The app composites the brand logo itself, after your code runs — the code',
  '   must NEVER call ctx.drawImage(logoImg, ...) or otherwise render logoImg in any way.',
  '   Fix: remove any logo-drawing code entirely. logoImg is passed for backward compatibility',
  '   only and must be ignored. Leave the top-left zone (roughly x:65–270, y:65–135) empty.',
  '',
  '3. CONTENT START: No content above y=220. Gap of 100–130px must exist below the reserved logo zone.',
  '   Fix: push content start down to y=220 minimum.',
  '',
  '4. CARD OVERFLOW: card bottom (cardY + cardH) must not exceed y=920.',
  '   Fix: reduce cardH so cardY + cardH <= 920.',
  '',
  '5. TEXT OVERFLOW: All text must use ctx.measureText + line wrapping. No text that assumes it fits.',
  '   Fix: add measuring + wrapping loop where missing.',
  '',
  '6. ELEMENT COLLISIONS: No two elements in the same space.',
  '   Fix: verify currentY tracking is used for stacked elements. Add currentY if missing.',
  '',
  '7. HARDCODED COLORS: All colors must use colors.* object. No raw hex/rgba values outside the colors definition.',
  '   Fix: replace any hardcoded color values with the appropriate colors.* key.',
  '',
  '8. VARIABLE DECLARATIONS: Every variable must be declared with const/let before use.',
  '   Fix: add missing declarations.',
  '',
  '9. PATH2D: Must use ctx.fill(path) / ctx.stroke(path). Not path.fill() or path.stroke().',
  '   Fix: correct any invalid Path2D calls.',
  '',
  '10. SHADOW RESET: After every element that sets shadowColor/shadowBlur, reset immediately after drawing:',
  '    ctx.shadowColor = \'transparent\'; ctx.shadowBlur = 0; ctx.shadowOffsetY = 0;',
  '    Fix: add reset where missing.',
  '',
  '11. ANIMATION: Every visible element must animate via options.progress. Nothing fully static.',
  '    Fix: wrap any static elements in globalAlpha or position animations.',
  '',
  '12. CTA CHECK: Only include a CTA if the ad copy explicitly contains one.',
  '    Fix: remove any invented CTA button or text.',
  '',
  '13. TEXTBASELINE DRIFT — After ctx.restore(), textBaseline silently reverts to \'alphabetic\'.',
  '    With alphabetic baseline, Y is the text BOTTOM, so a 64px number drawn at cardY+28',
  '    actually starts at cardY+28 minus ~51px = ABOVE the card top — numbers float out of cards.',
  '    Fix: add ctx.textBaseline = \'top\' at the start of EVERY ctx.save() block that draws text.',
  '    Every card section, stat section, and bottom row section must set textBaseline explicitly.',
  '',
  '14. ANIMATION Y DRIFT — Elements that use slide-in offsets like drawY = targetY + (1-eased)*40',
  '    must draw ALL sub-elements (text, icons, borders) using that same offset variable.',
  '    Never mix animated Y for the card background with hardcoded Y for the text inside.',
  '    Fix: ensure text Y = cardY + padding (where cardY is the animated variable, not a constant).',
  '',
  'RULES:',
  '- Make ONLY the corrections needed. Do not redesign or rewrite the entire function.',
  '- Do not change visual design intent, brand colors, layout style, or copy meaning.',
  '- Keep the function signature: function drawGraphic(ctx, width, height, logoImg, options)',
  '',
  'Return ONLY a valid JSON object:',
  '{ "jsCode": "corrected complete drawGraphic function", "corrections": ["brief list of what was fixed"] }',
  'No markdown. No code fences.',
].join('\n');

const userPrompt = 'Ad Copy (for CTA verification):\n' + adCopy + '\n\nCode to validate and correct:\n' + jsCode;

const validationRequestBody = JSON.stringify({
  model: 'google/gemini-3.5-flash',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: userPrompt }
  ],
  max_tokens: 32000
});

return [{ json: { validationRequestBody, originalJsCode: jsCode, designExplanation, brandId: meta.brandId, brandName: meta.brandName, layoutRefUsed: meta.layoutRefUsed } }];

const validatorResponse = $('Call Validator AI').first().json;
const meta = $('Build Validation Prompt').first().json;

function fixJsonEscapes(str) {
  return str.replace(/\\(?!["\\/bfnrtu])/g, '\\\\');
}

// Reverses JSON-style backslash escaping in a single left-to-right pass — see the identical
// helper in "Build Validation Prompt" for why the old sequential-replace chain was order-unsound
// and produced stray backslashes that broke `new Function(...)` downstream in every viewer.
function unescapeJsonEscapes(str) {
  return str.replace(/\\(u[0-9a-fA-F]{4}|n|t|r|"|'|\\)/g, function (_m, token) {
    switch (token[0]) {
      case 'n': return '\n';
      case 't': return '\t';
      case 'r': return '\r';
      case '"': return '"';
      case "'": return "'";
      case '\\': return '\\';
      default: return String.fromCharCode(parseInt(token.slice(1), 16));
    }
  });
}

function extractFromTruncated(str) {
  const m = str.match(/"jsCode"\s*:\s*"((?:[^"\\]|\\.)*)/s);
  if (!m || m[1].length < 100) return null;
  let code = unescapeJsonEscapes(m[1]);
  if (!code.trim().endsWith('}')) {
    // Only cut at a brace/semicolon that's back at the function body's own nesting level (one
    // curly deep, zero open parens/brackets) and not inside a string literal — the old version
    // grabbed the LAST '}' or ';' anywhere in the string, which can land inside a string literal
    // (e.g. ctx.fillText('Save 20% {bonus}', ...)) and leave the code broken even after closing it.
    let depthCurly = 0, depthParen = 0, depthSquare = 0;
    let inString = null;
    let bestCut = -1;
    for (let i = 0; i < code.length; i++) {
      const ch = code[i];
      if (inString) {
        if (ch === '\\') { i++; continue; }
        if (ch === inString) inString = null;
        continue;
      }
      if (ch === "'" || ch === '"' || ch === '`') { inString = ch; continue; }
      if (ch === '{') depthCurly++;
      else if (ch === '}') {
        depthCurly--;
        if (depthCurly === 1 && depthParen === 0 && depthSquare === 0) bestCut = i;
      } else if (ch === '(') depthParen++;
      else if (ch === ')') depthParen--;
      else if (ch === '[') depthSquare++;
      else if (ch === ']') depthSquare--;
      else if (ch === ';' && depthCurly === 1 && depthParen === 0 && depthSquare === 0) bestCut = i;
    }
    if (bestCut < 100) return null;
    code = code.substring(0, bestCut + 1) + '\n}';
  }
  return code;
}

// Actually constructs AND calls the code (a thrown/parse error inside `new Function(body)` only
// surfaces once the function runs) to confirm drawGraphic both parses and gets defined. This is
// what prevents genuinely broken code from ever reaching Supabase — instead of silently saving
// it and having it break with "Invalid escape in identifier" / "Global Code" every single time
// someone views it in History afterward.
function isValidDrawGraphic(code) {
  try {
    const result = new Function(code + "\nreturn typeof drawGraphic==='function';")();
    return result === true;
  } catch (e) {
    return false;
  }
}

function finalize(candidateCode, designExplanation) {
  const candidate = candidateCode && isValidDrawGraphic(candidateCode) ? candidateCode : null;
  const fallback = meta.originalJsCode && isValidDrawGraphic(meta.originalJsCode) ? meta.originalJsCode : null;
  const finalCode = candidate || fallback;
  if (!finalCode) {
    throw new Error('Generated infographic code failed validation and has no usable fallback. Please retry generation.');
  }
  return [{ json: { jsCode: finalCode, designExplanation: designExplanation || '', brandId: meta.brandId, brandName: meta.brandName, layoutRefUsed: meta.layoutRefUsed } }];
}

// If validator was skipped (null request body means renderer parsing already failed gracefully)
if (!meta.validationRequestBody) {
  return finalize(meta.originalJsCode, meta.designExplanation);
}

const raw = validatorResponse.choices?.[0]?.message?.content;

// Validator failed — fall back to original renderer output
if (!raw) {
  return finalize(meta.originalJsCode, meta.designExplanation);
}

let cleaned = raw.trim();
if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```[\w]*\n?/, '').replace(/\n?```$/, '').trim();
}

let parsed;
try { parsed = JSON.parse(cleaned); }
catch(e) {
  try { parsed = JSON.parse(fixJsonEscapes(cleaned)); }
  catch(e2) {
    const extracted = extractFromTruncated(cleaned);
    if (extracted) return finalize(extracted, meta.designExplanation);
    // Validator output unparseable — use original
    return finalize(meta.originalJsCode, meta.designExplanation);
  }
}

return finalize(parsed.jsCode || meta.originalJsCode, parsed.designExplanation || meta.designExplanation);
